import subprocess
import time
import os

today = format(time.strftime("%Y/%m/%d %H:%M:%S"))

# Get the directory where this script is located
script_dir = os.path.dirname(os.path.abspath(__file__))

print('\n-- git add . -----------------------------------------------------------------------------\n')
subprocess.run(['git', 'add', '.'], cwd=script_dir)
print(f'git add .')

print(f'\n-- git commit -m"Updated files: {today}" ------------------------------------------------\n')
subprocess.run(['git', 'commit', '-m', f'Updated files: {today}'], cwd=script_dir)

print('\n-- git push origin dev -------------------------------------------------------------------\n')
subprocess.run(['git', 'push', 'origin', 'dev'], cwd=script_dir)

print('\n------------------------------------------------------------------------------------------\n')

